<template>
  <div class="app-container">
    <h2>本地财务与对账</h2><operation-scope v-model="target" @change="changeTenant" />
    <el-alert v-if="error" :title="error" type="error" :closable="false" />
    <el-tabs v-model="tab">
      <el-tab-pane label="收款台账" name="payments"><el-button size="small" icon="el-icon-refresh" @click="load">刷新</el-button><el-table v-loading="loading" :data="report.records" border class="data-table"><el-table-column prop="order_id" label="订单" min-width="210" /><el-table-column prop="member_id" label="会员" width="90" /><el-table-column prop="gross_amount" label="结算 / 元" /><el-table-column prop="discount_amount" label="优惠 / 元" /><el-table-column prop="paid_amount" label="实付 / 元" /><el-table-column prop="refunded_amount" label="已退 / 元" /><el-table-column label="净收 / 元"><template slot-scope="scope">{{ money(Number(scope.row.paid_amount) - Number(scope.row.refunded_amount)) }}</template></el-table-column><el-table-column prop="status" label="状态" /><el-table-column label="分账"><template slot-scope="scope"><el-button v-hasPermi="['operator:operations:write']" type="text" :disabled="saving" @click="split(scope.row)">记入分账</el-button></template></el-table-column></el-table><pagination v-show="report.total > 0" :total="report.total" :page.sync="page" :limit.sync="size" @pagination="load" /></el-tab-pane>
      <el-tab-pane label="退款流水" name="refunds"><el-table :data="report.refunds" border><el-table-column prop="id" label="流水号" width="90" /><el-table-column prop="order_id" label="订单" min-width="200" /><el-table-column prop="amount" label="金额 / 元" /><el-table-column prop="reason" label="原因" /><el-table-column prop="actor_id" label="操作人" /><el-table-column prop="created_at" label="时间" min-width="170" /></el-table></el-tab-pane>
      <el-tab-pane label="分成配置与台账" name="splits"><el-form inline><el-form-item label="平台分成"><el-input-number v-model="rate" :min="0" :max="100" :precision="2" /> %</el-form-item><el-form-item label="站点分成">{{ money(100 - rate) }} %</el-form-item><el-button v-hasPermi="['operator:operations:write']" :loading="saving" @click="saveRule">保存比例</el-button></el-form><el-alert title="比例只作用于新分账；退款按原比例快照冲正。这里只生成台账，不进行真实提现。以下展示最近100条记录。" type="info" :closable="false" /><el-table :data="report.splits" border class="data-table"><el-table-column prop="order_id" label="订单" min-width="210" /><el-table-column label="类型" width="90"><template slot-scope="scope"><el-tag :type="Number(scope.row.refund_id) ? 'warning' : 'success'">{{ Number(scope.row.refund_id) ? '退款冲正' : '首次分账' }}</el-tag></template></el-table-column><el-table-column prop="platform_rate" label="比例快照 / %" /><el-table-column prop="platform_amount" label="平台金额 / 元" /><el-table-column prop="station_amount" label="站点金额 / 元" /><el-table-column prop="created_at" label="时间" min-width="170" /></el-table></el-tab-pane>
      <el-tab-pane label="本地对账" name="reconcile"><el-form inline><el-form-item label="业务日期"><el-date-picker v-model="businessDay" value-format="yyyy-MM-dd" type="date" /></el-form-item><el-button v-hasPermi="['operator:operations:write']" type="primary" :loading="saving" @click="reconcile">生成对账批次</el-button></el-form><el-alert title="核对该日创建的本地付款及其截至当前的退款、余额流水和分账。未实付历史订单不计为资金差异。每次执行保留新批次。" type="info" :closable="false" /><el-table :data="report.batches" border class="data-table"><el-table-column prop="id" label="批次" width="85" /><el-table-column prop="business_day" label="业务日" /><el-table-column prop="checked_count" label="核对笔数" /><el-table-column prop="difference_count" label="差异笔数" /><el-table-column prop="excluded_count" label="未纳入收款" /><el-table-column label="操作"><template slot-scope="scope"><el-button type="text" @click="inspect(scope.row)">逐笔结果</el-button><el-button v-hasPermi="['operator:operations:write']" type="text" @click="note(scope.row)">处理备注</el-button></template></el-table-column></el-table><h4>对账处理备注（最近100条）</h4><el-table :data="report.notes" size="small"><el-table-column prop="batch_id" label="批次" width="90" /><el-table-column prop="note" label="说明" /><el-table-column prop="actor_id" label="操作人" width="100" /></el-table></el-tab-pane>
    </el-tabs>
    <el-dialog title="逐笔对账结果" :visible.sync="detailVisible" width="800px"><el-table :data="details" size="small"><el-table-column prop="orderId" label="订单" min-width="200" /><el-table-column prop="paid" label="实付" /><el-table-column prop="walletDebit" label="余额扣款" /><el-table-column prop="refunded" label="退款" /><el-table-column prop="walletCredit" label="余额入账" /><el-table-column prop="split" label="净分账" /><el-table-column label="结果"><template slot-scope="scope"><el-tag :type="scope.row.matched ? 'success' : 'danger'">{{ scope.row.matched ? '一致' : '有差异' }}</el-tag></template></el-table-column></el-table></el-dialog>
  </div>
</template>
<script>
import OperationScope from './scope'
import { getOperations, saveOperation, formatMoney } from '@/api/operator/operations'
export default {
  name: 'OperationsFinance', components: { OperationScope },
  data() { return { target: this.$route.query.targetTenantId || '', tab: 'payments', page: 1, size: 10, report: { records: [], refunds: [], splits: [], batches: [], notes: [], total: 0, rule: {}}, rate: 10, businessDay: new Date().toLocaleDateString('sv-SE'), sequence: 0, context: 0, loading: false, saving: false, error: '', details: [], detailVisible: false } },
  created() { this.load() },
  methods: {
    money: formatMoney,
    changeTenant() { this.context++; this.page = 1; this.report = { records: [], refunds: [], splits: [], batches: [], notes: [], total: 0, rule: {}}; this.detailVisible = false; this.details = []; this.rate = 10; this.load() },
    params(extra) { return { targetTenantId: this.target || undefined, ...extra } },
    async load() { const sequence = ++this.sequence; this.loading = true; this.error = ''; try { const { data } = await getOperations('finance', this.params({ page: this.page, size: this.size })); if (sequence !== this.sequence) return; this.report = data; this.rate = Number(data.rule.platform_rate) } catch (error) { if (sequence === this.sequence) { this.report = { records: [], refunds: [], splits: [], batches: [], notes: [], total: 0, rule: {}}; this.error = '财务数据加载失败，请重试' } } finally { if (sequence === this.sequence) this.loading = false } },
    async mutate(path, data) { if (this.saving) return; this.saving = true; try { const result = await saveOperation(path, this.params(data)); this.$message.success('本地台账已更新'); await this.load(); return result } finally { this.saving = false } },
    split(row) { return this.mutate('split', { orderId: row.order_id }) },
    saveRule() { return this.mutate('split/rule', { platformRate: this.rate, version: this.report.rule.version }) },
    async reconcile() { if (!this.businessDay) return this.$message.warning('请选择业务日期'); await this.mutate('reconcile', { businessDay: this.businessDay }) },
    inspect(row) { try { this.details = JSON.parse(row.details); this.detailVisible = true } catch (error) { this.$message.error('对账明细格式异常') } },
    async note(row) { const context = this.context; const { value } = await this.$prompt('输入差异处理说明，保留原批次结果', '添加处理备注', { inputValidator: value => !!value && value.length <= 255 }); if (context !== this.context) return; await this.mutate('reconcile/note', { batchId: row.id, reason: value }) }
  }
}
</script>
<style scoped>.data-table { margin-top: 18px; } h2 { color: #26344f; }</style>
